// HW1 timing program, written by the course staff. Do not edit this file.
//
// Build: g++ -std=c++17 -O0 timing.cpp matmul.cpp -o timing
// Run:   ./timing <your 9-digit student ID>
//
// For every size it:
//   - makes random matrices A and B from your student ID (same ID, same matrices, on any computer),
//   - calls your matmul() several times, with new A and B each time, and times only the call,
//   - checks every call: for 3 random vectors x, C·x must match A·(B·x)
//     within relative error 1e-4 (error = ||C·x - A·(B·x)|| / ||A·(B·x)||, 2-norm),
//   - checks that matmul doesn't change A or B and uses one thread,
//   - measures peak memory (each size runs in its own process).
// It writes everything to results.csv in the folder you run it from.

#include "matmul.h"

#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <ctime>
#include <filesystem>
#include <fstream>
#include <random>
#include <string>
#include <vector>

#include <signal.h>
#include <sys/resource.h>
#include <sys/types.h>
#include <sys/utsname.h>
#include <sys/wait.h>
#include <unistd.h>
#ifdef __APPLE__
#include <sys/sysctl.h>
#endif

namespace {

const char *VERSION = "hw1-timing 1.1";
const double TOLERANCE = 1e-4;
const int CHECK_VECTORS = 3;
const unsigned TIMEOUT_S = 1200;  // per size; a size that takes longer counts as failed
const double ONE_RUN_S = 2.0;     // a first run this long is the measurement
const double BUDGET_S = 1.0;      // otherwise, more runs for about this long
const int MIN_RUNS = 3, MAX_RUNS = 1000;
const double MAX_CPU_PER_WALL = 1.5;  // more means matmul used threads
const double MIN_WALL_S = 0.05;       // shorter is too noisy to judge CPU / wall
const char *SUSPICIOUS[] = {"<thread>", "std::thread", "<future>", "std::async", "pthread", "omp.h", "pragma omp"};

struct Size { int m, n, p; };
const Size SIZES[] = {
    {16, 16, 16},       {32, 32, 32},       {64, 64, 64},       {128, 128, 128},
    {256, 256, 256},    {512, 512, 512},    {1000, 1000, 1000}, {1023, 1023, 1023},
    {1024, 1024, 1024}, {1025, 1025, 1025}, {2048, 2048, 2048},
    {2048, 64, 2048},   {64, 2048, 64},
};

// std distributions can differ between Linux and Mac, so we make the doubles from mt19937_64 ourselves.
std::mt19937_64 make_rng(uint32_t id, const Size &s, uint32_t stream) {
    std::seed_seq seq{id, uint32_t(s.m), uint32_t(s.n), uint32_t(s.p), stream};
    return std::mt19937_64(seq);
}

double uniform(std::mt19937_64 &g) { return std::ldexp(double(g() >> 11), -52) - 1.0; }  // in [-1, 1)

uint64_t hash_doubles(const std::vector<double> &v) {
    uint64_t h = 1469598103934665603ULL;
    for (double d : v) {
        uint64_t bits;
        std::memcpy(&bits, &d, sizeof bits);
        h = (h ^ bits) * 1099511628211ULL;
    }
    return h;
}

// Freivalds' check: largest relative error over CHECK_VECTORS random vectors.
double check(const std::vector<double> &A, const std::vector<double> &B, const std::vector<double> &C,
             const Size &s, std::mt19937_64 &rng) {
    const int m = s.m, n = s.n, p = s.p;
    std::vector<double> x(p), Bx(n), ABx(m);
    double worst = 0.0;
    for (int t = 0; t < CHECK_VECTORS; t++) {
        for (double &v : x) v = uniform(rng);
        for (int i = 0; i < n; i++) {
            double sum = 0.0;
            for (int j = 0; j < p; j++) sum += B[(size_t)i * p + j] * x[j];
            Bx[i] = sum;
        }
        for (int i = 0; i < m; i++) {
            double sum = 0.0;
            for (int k = 0; k < n; k++) sum += A[(size_t)i * n + k] * Bx[k];
            ABx[i] = sum;
        }
        double diff2 = 0.0, ref2 = 0.0;
        for (int i = 0; i < m; i++) {
            double cx = 0.0;
            for (int j = 0; j < p; j++) cx += C[(size_t)i * p + j] * x[j];
            diff2 += (cx - ABx[i]) * (cx - ABx[i]);
            ref2 += ABx[i] * ABx[i];
        }
        double err = std::sqrt(diff2 / ref2);
        if (!(err <= worst)) worst = err;  // also keeps NaN
    }
    return worst;
}

double peak_memory_mb() {
    struct rusage ru;
    getrusage(RUSAGE_SELF, &ru);
#ifdef __APPLE__
    return ru.ru_maxrss / (1024.0 * 1024.0);  // bytes on macOS
#else
    return ru.ru_maxrss / 1024.0;  // KB on Linux
#endif
}

struct Result {
    double time_s;
    int runs;
    double error;  // of run 1
    int bad_run;   // first later run that failed, or 0
    double bad_error;
    int input_changed;
    double cpu_per_wall;
    double peak_mb, extra_mb;
};

// Runs in a child process: one size, start to finish.
Result run_size(const Size &s, uint32_t id) {
    const int m = s.m, n = s.n, p = s.p;
    std::vector<double> A((size_t)m * n), B((size_t)n * p), C((size_t)m * p);
    std::mt19937_64 data = make_rng(id, s, 0), junk = make_rng(id, s, 1), vectors = make_rng(id, s, 2);
    Result res{};
    double wall = 0.0, cpu = 0.0;

    // New A and B every run, so saving the last answer doesn't help. Junk in C: matmul must overwrite it.
    auto new_inputs = [&] {
        for (double &v : A) v = uniform(data);
        for (double &v : B) v = uniform(data);
        for (double &v : C) v = 1e6 * uniform(junk);
    };
    auto run = [&](int k) {
        const uint64_t hash_a = hash_doubles(A), hash_b = hash_doubles(B);
        const std::clock_t c0 = std::clock();
        const auto t0 = std::chrono::steady_clock::now();
        matmul(A.data(), B.data(), C.data(), m, n, p);
        const auto t1 = std::chrono::steady_clock::now();
        const std::clock_t c1 = std::clock();
        const double t = std::chrono::duration<double>(t1 - t0).count();
        wall += t;
        cpu += double(c1 - c0) / CLOCKS_PER_SEC;
        if (hash_doubles(A) != hash_a || hash_doubles(B) != hash_b) res.input_changed = 1;
        const double e = check(A, B, C, s, vectors);
        if (k == 1) {
            res.error = e;
        } else if (!(e <= TOLERANCE) && !res.bad_run) {  // also catches NaN
            res.bad_run = k;
            res.bad_error = e;
        }
        return t;
    };

    new_inputs();
    std::vector<double> times;
    times.reserve(MAX_RUNS);
    std::mt19937_64 spare = vectors;  // run our own code once, so its memory isn't counted as matmul's
    check(A, B, C, s, spare);
    hash_doubles(A);
    std::clock();
    std::chrono::steady_clock::now();
    const double base_mb = peak_memory_mb();

    // First run (warm-up). If it took ONE_RUN_S or more, it is the measurement.
    // Otherwise: median of more runs, for about BUDGET_S.
    const double first = run(1);
    if (first < ONE_RUN_S) {
        const auto start = std::chrono::steady_clock::now();
        auto elapsed = [&] { return std::chrono::duration<double>(std::chrono::steady_clock::now() - start).count(); };
        while ((int)times.size() < MAX_RUNS && ((int)times.size() < MIN_RUNS || elapsed() < BUDGET_S)) {
            new_inputs();
            times.push_back(run((int)times.size() + 2));
        }
    }

    if (times.empty()) {
        res.time_s = first;
        res.runs = 1;
    } else {
        std::sort(times.begin(), times.end());
        res.time_s = times[times.size() / 2];
        res.runs = (int)times.size();
    }
    res.cpu_per_wall = wall >= MIN_WALL_S ? cpu / wall : 0.0;
    res.peak_mb = peak_memory_mb();
    res.extra_mb = res.peak_mb - base_mb;
    return res;
}

std::string trim(std::string s) {
    size_t a = s.find_first_not_of(" \t\"\n"), b = s.find_last_not_of(" \t\"\n");
    return a == std::string::npos ? "" : s.substr(a, b - a + 1);
}

std::string csv_safe(std::string s) {
    for (char &c : s)
        if (c == ',' || c == '\n') c = ' ';
    return s;
}

std::string cpu_name() {
#ifdef __APPLE__
    char buf[256];
    size_t len = sizeof buf;
    if (sysctlbyname("machdep.cpu.brand_string", buf, &len, nullptr, 0) == 0) return buf;
#else
    std::ifstream f("/proc/cpuinfo");
    std::string line;
    while (std::getline(f, line))
        if (line.rfind("model name", 0) == 0 || line.rfind("Model", 0) == 0) return trim(line.substr(line.find(':') + 1));
#endif
    struct utsname u;
    return uname(&u) == 0 ? u.machine : "unknown";
}

std::string os_name() {
    std::string name;
#ifndef __APPLE__
    std::ifstream f("/etc/os-release");
    std::string line;
    while (std::getline(f, line))
        if (line.rfind("PRETTY_NAME=", 0) == 0) name = trim(line.substr(12)) + "; ";
#endif
    struct utsname u;
    if (uname(&u) == 0) name += std::string(u.sysname) + " " + u.release + " " + u.machine;
    return name;
}

std::string compiler_name() {
#if defined(__clang__)
#if defined(__apple_build_version__)
    return std::string("Apple clang ") + __clang_version__;
#else
    return std::string("clang ") + __clang_version__;
#endif
#elif defined(__GNUC__)
    return std::string("g++ ") + __VERSION__;
#else
    return "unknown";
#endif
}

// What the build flags look like from inside the program. The handout command is g++ -std=c++17 -O0.
std::string flags(std::vector<std::string> &warnings) {
    (void)warnings;
    std::string f = "C++ " + std::to_string(__cplusplus);
#ifdef __OPTIMIZE__
    f += "; optimized (not -O0)";
    warnings.push_back("built with optimization; use -O0");
#else
    f += "; -O0";
#endif
#ifdef __FAST_MATH__
    f += "; -ffast-math";
    warnings.push_back("built with -ffast-math; don't use it");
#endif
#ifdef _OPENMP
    f += "; -fopenmp";
    warnings.push_back("built with -fopenmp; don't use it");
#endif
#if defined(__AVX__) || defined(__AVX2__) || defined(__AVX512F__) || defined(__FMA__)
    f += "; -march (AVX)";
    warnings.push_back("built with -march or AVX flags; don't use them");
#endif
    return f;
}

// Warns early if matmul.cpp uses threads. run_size() catches them too.
void scan_matmul(std::vector<std::string> &warnings) {
    std::ifstream f(std::filesystem::current_path() / "matmul.cpp");
    if (!f) {
        warnings.push_back("can't read matmul.cpp in this folder, so it wasn't checked");
        return;
    }
    std::string line;
    for (int no = 1; std::getline(f, line); no++)
        for (const char *word : SUSPICIOUS)
            if (line.find(word) != std::string::npos) {
                warnings.push_back("matmul.cpp line " + std::to_string(no) + " has " + word + ": " +
                                   trim(line).substr(0, 60));
                break;
            }
}

std::string size_name(const Size &s) {
    char buf[64];
    if (s.m == s.n && s.n == s.p)
        std::snprintf(buf, sizeof buf, "N=%d", s.m);
    else
        std::snprintf(buf, sizeof buf, "%dx%dx%d", s.m, s.n, s.p);
    return buf;
}

}  // namespace

int main(int argc, char **argv) {
    if (argc != 2 || std::strlen(argv[1]) != 9 ||
        std::strspn(argv[1], "0123456789") != 9) {
        std::fprintf(stderr, "Usage: %s <your 9-digit student ID>\n", argv[0]);
        return 2;
    }
    const uint32_t id = (uint32_t)std::strtoul(argv[1], nullptr, 10);

    std::vector<std::string> warnings;
    const std::string build = flags(warnings);
    for (auto &w : warnings) w += " (see the build command in the handout)";
    scan_matmul(warnings);
    std::string all_warnings;
    for (const auto &w : warnings) {
        std::printf("WARNING: %s\n", w.c_str());
        all_warnings += (all_warnings.empty() ? "" : "; ") + w;
    }

    const std::filesystem::path out = std::filesystem::current_path() / "results.csv";
    std::ofstream csv(out);
    if (!csv) {
        std::fprintf(stderr, "Can't write %s\n", out.string().c_str());
        return 2;
    }
    char date[64];
    std::time_t now = std::time(nullptr);
    std::strftime(date, sizeof date, "%Y-%m-%d %H:%M", std::localtime(&now));
    csv << "# " << VERSION << "\n"
        << "# student_id: " << argv[1] << "\n"
        << "# date: " << date << "\n"
        << "# cpu: " << csv_safe(cpu_name()) << "\n"
        << "# os: " << csv_safe(os_name()) << "\n"
        << "# compiler: " << csv_safe(compiler_name()) << "\n"
        << "# flags: " << csv_safe(build) << "\n"
        << "# warnings: " << csv_safe(all_warnings.empty() ? "none" : all_warnings) << "\n"
        << "m,n,p,time_s,runs,peak_memory_mb,extra_memory_mb,relative_error,result\n";
    csv.flush();

    std::printf("%-14s %12s %6s %12s %11s %14s  %s\n", "size", "time (s)", "runs", "memory (MB)", "extra (MB)",
                "rel. error", "result");
    int failed = 0;
    for (const Size &s : SIZES) {
        std::printf("%-14s ", size_name(s).c_str());
        std::fflush(stdout);
        int fd[2];
        if (pipe(fd) != 0) { std::perror("pipe"); return 2; }
        pid_t pid = fork();
        if (pid < 0) { std::perror("fork"); return 2; }
        if (pid == 0) {
            close(fd[0]);
            alarm(TIMEOUT_S);
            Result r = run_size(s, id);
            std::fflush(stdout);
            ssize_t ignored = write(fd[1], &r, sizeof r);
            (void)ignored;
            _exit(0);
        }
        close(fd[1]);
        Result r{};
        ssize_t got = 0;
        while (got < (ssize_t)sizeof r) {
            ssize_t k = read(fd[0], (char *)&r + got, sizeof r - got);
            if (k <= 0) break;
            got += k;
        }
        close(fd[0]);
        int status = 0;
        waitpid(pid, &status, 0);

        std::string result;
        bool finished = got == (ssize_t)sizeof r && WIFEXITED(status) && WEXITSTATUS(status) == 0;
        if (!finished) {
            if (WIFSIGNALED(status) && WTERMSIG(status) == SIGALRM)
                result = "timeout";
            else if (WIFSIGNALED(status))
                result = std::string("crash (") + strsignal(WTERMSIG(status)) + ")";
            else
                result = "crash";
        } else if (r.input_changed) {
            result = "fail (A or B changed)";
        } else if (r.cpu_per_wall > MAX_CPU_PER_WALL) {
            char buf[64];
            std::snprintf(buf, sizeof buf, "fail (%.1fx CPU time: more than one thread)", r.cpu_per_wall);
            result = buf;
        } else if (!(r.error <= TOLERANCE)) {
            result = "fail";
        } else if (r.bad_run) {
            char buf[64];
            std::snprintf(buf, sizeof buf, "fail (run %d wrong: error %.3g)", r.bad_run, r.bad_error);
            result = buf;
        } else {
            result = "pass";
        }
        if (result != "pass") failed++;

        if (finished) {
            std::printf("%12.6f %6d %12.1f %11.1f %14.3g  %s\n", r.time_s, r.runs, r.peak_mb, r.extra_mb, r.error,
                        result.c_str());
            char row[256];
            std::snprintf(row, sizeof row, "%d,%d,%d,%.9f,%d,%.1f,%.1f,%.3e,%s\n", s.m, s.n, s.p, r.time_s, r.runs,
                          r.peak_mb, r.extra_mb, r.error, csv_safe(result).c_str());
            csv << row;
        } else {
            std::printf("%12s %6s %12s %11s %14s  %s\n", "-", "-", "-", "-", "-", result.c_str());
            csv << s.m << "," << s.n << "," << s.p << ",,,,,," << csv_safe(result) << "\n";
        }
        csv.flush();
    }

    const int total = (int)(sizeof SIZES / sizeof SIZES[0]);
    if (failed == 0)
        std::printf("\nAll %d sizes pass. Results are in %s\n", total, out.string().c_str());
    else
        std::printf("\n%d of %d sizes failed. Results are in %s\n", failed, total, out.string().c_str());
    return failed == 0 ? 0 : 1;
}
